// Block (composition) — a content wrapper with a conditional loading scrim.
// Stack owns scrim arrangement; Spinner owns loading status and this Block owns busy-state composition.
import type { ReactNode, Ref } from "react";
import { Spinner } from "../components/Spinner";
import { Stack } from "../layouts/Stack";
import "./LoadingOverlay.css";

export interface LoadingOverlayProps {
  isLoading: boolean;
  label?: string;
  children: ReactNode;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function LoadingOverlay({
  isLoading,
  label = "Loading…",
  children,
  className,
  ref,
}: LoadingOverlayProps) {
  return (
    <div
      ref={ref}
      aria-busy={isLoading}
      className={className ? `sd-loadingoverlay ${className}` : "sd-loadingoverlay"}
    >
      {children}
      {isLoading && (
        <Stack
          className="sd-loadingoverlay__scrim"
          align="center"
          justify="center"
          gap="x-small"
          aria-live="polite"
        >
          <Spinner aria-label={label} />
          <span aria-hidden="true" className="sd-loadingoverlay__label sd-type-label-medium">
            {label}
          </span>
        </Stack>
      )}
    </div>
  );
}

.sd-loadingoverlay {
  position: relative;
}

.sd-loadingoverlay__scrim {
  position: absolute;
  z-index: 1;
  inset: 0;
}
